/**
* Fetches a resource from the network
* @param url defines the url to fetch the resource from
* @param options defines the options to use when fetching the resource
* @returns a promise that resolves when the resource is fetched
* @internal
*/
async function _FetchAsync(url, options) {
	const method = options.method || "GET";
	return await new Promise((resolve, reject) => {
		const request = new WebRequest();
		request.addEventListener("readystatechange", () => {
			if (request.readyState == 4) if (request.status == 200) {
				const headerValues = {};
				if (options.responseHeaders) for (const header of options.responseHeaders) headerValues[header] = request.getResponseHeader(header) || "";
				resolve({
					response: request.response,
					headerValues
				});
			} else reject(`Unable to fetch data from ${url}. Error code: ${request.status}`);
		});
		request.open(method, url);
		request.send();
	});
}
